insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada) values
('PIR 19', 'Pregunta 1', 'Un niño, ante la pregunta de por qué no se debe pegar a un compañero, contesta: "porque si la profesora te ve, te castiga". De acuerdo con Kohlberg, ¿en qué nivel de desarrollo moral se encuentra?:', '["Nivel preconvencional.", "Nivel instrumental.", "Nivel formal.", "Nivel intuitivo."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 2', 'Ante dos filas con el mismo número de monedas cada una, un niño cree que la fila más larga tiene más monedas que la final más corta. ¿En qué etapa de Piaget se encuentra este niño?:', '["Operaciones formales.", "Operaciones concretas.", "Preoperacional o intuitiva.", "Sensoriomotora."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 3', 'De acuerdo con la propuesta de Erik Erikson, en la mediana edad la crisis o desafío que las personas han de abordar se denomina:', '["Intimidad.", "Productividad.", "Integridad.", "Generatividad."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 4', 'Una técnica de instrucción mediante la que alguien más experto proporciona un apoyo temporal al niño en aquello que está cercano a ser comprendido o en habilidades próximas a ser alcanzadas por el niño, se denomina:', '["Aprendizaje vicario.", "Aprendizaje proximal.", "Zona de desarrollo próximo.", "Andamiaje."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 5', 'Triandis (1995) propone los términos idiocentrismo y alocentrismo para designar a las tendencias personales que constituyen reflejos de la cultura. Algunas diferencias entre los sujetos idiocéntricos y alocéntricos son que:', '["Los sujetos idiocéntricos tienden hacia la dominancia mientras que los alocéntricos muestran niveles más altos de conformidad.", "Los sujetos idiocéntricos están más motivados por el logro mientras que los sujetos alocéntricos son más propensos a experimentar estrés.", "Los sujetos idiocéntricos son más afables mientras que los sujetos alocéntricos son más competitivos.", "Los sujetos idiocéntricos son más afables y los alocéntricos más optimistas."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 6', 'Nos enfadamos cuando nuestro equipo de fútbol pierde una liga, nos alegramos cuando nuestro mejor amigo consigue el trabajo que anhelaba y sufrimos cuando alguien querido nos deja. Para Frijda, la razón que explica estas emociones es la:', '["Ley del Interés.", "Ley de la realidad aparente.", "Ley de la conservación del momento emocional.", "Ley del cierre."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 7', 'La alerta alimentaria producida tras un brote de listeriosis asociada a una marca de carne mechada produjo una drástica disminución del consumo no solo de este tipo de productos sino de otros similares. El juicio del consumidor estuvo afectado por uno de los heurísticos descritos por Kahneman y Tversky, el heurístico de:', '["Conservadurismo cognitivo.", "Disponibilidad.", "Actitud.", "Control."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 8', 'Markus (1977) propone el concepto de "esquemas del self" que indica que, del mismo modo que formamos estructuras cognitivas sobre otros fenómenos, también formamos estas estructuras en la relación con el self. Respecto a estos esquemas del self podemos afirmar que:', '["Afectan a la rapidez con que procesamos información relativa a nosotros mismos pero no influyen en la memoria y recuerdo de esta información.", "Son generalizaciones cognitivas sobre nosotros mismos por lo que no están afectadas por las influencias culturales.", "Como estructuras cognitivas no están relacionadas con variables afectivas o motivacionales.", "Representan no solo la consideración actual de nuestro self sino nuestros \"selves posibles\" (como lo que creemos que llegaremos a ser o lo que nos gustaría llegar a ser)."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 9', '¿A qué tipo de covariación entre genes y ambiente nos referimos si son los propios padres los que trasmiten tanto el genotipo como el ambiente propicio para el desarrollo de un rasgo?:', '["Activa.", "Específica.", "Pasiva.", "Reactiva."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 10', 'Atendiendo al modelo cúbico de la estructura del intelecto de Guilford, señale qué facetas de las dimensiones "operación mental" y "contenido" intervienen si se le pide a un niño que diga todos los animales mamíferos que conoce:', '["Convergente semántico.", "Divergente semántico.", "Convergente simbólico.", "Divergente simbólico."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 11', 'Según el modelo jerárquico de H.J. Eysenck, señale en qué nivel se sitúa el hecho de que una persona se enfade habitualmente y tenga sentimientos de culpabilidad y ansiedad tanto en casa como en el trabajo:', '["Respuesta estereotipada.", "Patrón de respuesta.", "Hábito.", "Rasgo."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 12', 'Señale qué se puede afirmar, en general, sobre la estabilidad de la personalidad a lo largo del tiempo:', '["La personalidad es menos estable en periodos cortos de tiempo que en periodos considerados más largos.", "Es más clara la estabilidad de la inteligencia que la de la personalidad.", "Las puntuaciones en los test de personalidad son muy estables a lo largo del ciclo vital.", "No hay diferencias individuales en la estabilidad durante el desarrollo."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 13', 'Mientras estudias con la ventana abierta oyes una canción y tu mente se traslada al verano y la última fiesta en la que conociste a alguien muy interesante, de quien no has vuelto a saber. Tu mente va de una imagen a otra y cuando te das cuenta han pasado 10 minutos. Este proceso refleja, según el modelo de R. J. Sternberg:', '["Cómo operan los \"componentes\" o procesos elementales de información.", "El funcionamiento de los correlatos de la inteligencia.", "La gran asociación entre capacidad auditiva y memoria, base de las diferencias individuales en inteligencia.", "La asociación entre capacidad auditiva y atención focal."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 14', 'Respecto de la relación entre la inteligencia (cristalizada y fluida) y la edad, señale la opción correcta:', '["A partir de la edad en que alcanzan el máximo nivel, la fluida experimenta un declive más pronunciado que la cristalizada.", "A partir de la edad en que alcanzan el máximo nivel, ambos tipos de inteligencia se mantienen en el tiempo sin variación.", "El curso de ambos tipos de inteligencias es de tipo fluctuante, sin que exista un patrón definido de incremento o decremento asociado a la edad.", "El curso de ambos tipos de inteligencia es estable a partir de la adolescencia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 15', 'En el Modelo de los Cinco Grandes, de McCrae y Costa, ¿a qué dimensión pertenece la faceta de impulsividad?:', '["Neuroticismo.", "Extraversión.", "Búsqueda de sensaciones.", "Responsabilidad."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 16', 'En el modelo de los Cinco Grandes, hay una dimensión de personalidad cuyos niveles medios aumentan consistentemente a lo largo del ciclo vital. ¿De cuál se trata?:', '["La responsabilidad.", "La extraversión.", "La emocionalidad negativa.", "La apertura a la experiencia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 17', 'Con relación a las causas de las diferencias individuales, ¿qué es la heredabilidad amplia?:', '["La proporción de varianza fenotípica explicada por la varianza genotípica", "La proporción de varianza genotípica explicada por la varianza fenotípica.", "La proporción de varianza fenotípica aditiva explicada por la varianza genotípica.", "La proporción de varianza fenotípica explicada por la varianza genotípica aditiva."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 18', 'Los "hechos aritméticos" (operaciones automatizadas que se almacenan en la memoria verbal) son recuperados de la memoria por:', '["La corteza prefrontal dorsolateral.", "La circunvolución fusiforme.", "La circunvolución angular.", "El surco intraparietal."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 19', 'La principal vía eferente de la formación hipocampal es:', '["El núcleo supraquiasmático.", "La circunvolución dentada.", "El fórnix.", "El campo CA3."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 20', 'Resulta esencial para detectar el disgusto en los otros y experimentar el propio disgusto:', '["La circunvolución fusiforme.", "La ínsula anterior.", "La unión temporoparietal.", "El surco temporal superior."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 21', '¿Qué proteína es necesaria para el establecimiento de la potenciación a largo plazo de larga duración (PLP-LD):', '["El óxido nítrico liberado por la neurona presináptica.", "La entrada de iones calcio y activación subsiguiente de enzimas como la CaM-KII.", "La activación de los receptores de NMDA activados por ligando y por voltaje.", "La enzima PKM-zeta, al facilitar el desplazamiento de los receptores AMPA a la membrana terminal."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 22', 'La extinción de las respuestas emocionales condicionadas se relaciona, fundamentalmente, con la actividad de:', '["La corteza prefrontal ventromedial.", "La ínsula.", "La corteza cingulada posterior.", "El núcleo accumbens."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 23', 'Durante el desarrollo embrionario, la ausencia de hormona inhibidora del sistema de Müller se relaciona con:', '["El síndrome de insensibilidad a los andrógenos.", "La alteración del gen SRY (sex-determining region Y).", "La inhibición en la síntesis de dihidrotestosterona.", "No se produce desfeminización."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 24', 'Las proteínas responsables de producir y mantener estables las concentraciones de sodio y potasio a ambos lados de la membrana y por tanto de asegurar la estabilidad del potencial de reposo y permitir el futuro potencial de acción son:', '["Los canales de sodio y potasio pasivos.", "Los canales de sodio y potasio controlados por voltaje.", "Las bombas de sodio-potasio.", "Las proteínas G."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 25', 'En la transmisión sináptica, para que se libere con éxito el neurotransmisor en el espacio sináptico es necesario:', '["Que se transmita un potencial excitatorio postsináptico a lo largo del axón y llegue al botón terminal.", "Que se abran los canales de calcio controlados por voltaje, y entre calcio en el botón terminal.", "Que las vesículas que contienen el neurotransmisor se fusionen con las zonas activas de la membrana postsináptica.", "Que se activen los autorreceptores presinápticos."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 26', 'El sueño REM:', '["Está producido por la estimulación colinérgica de la formación reticular pontina.", "Está producido por la estimulación de las neuronas serotoninérgicas del núcleo del rafe.", "Está asociado a una disminución de la temperatura corporal y el consumo de energía.", "Presenta un EEG lento y de alto voltaje."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 27', 'El área preóptica ventrolateral (APOvl):', '["Es una región promotora del sueño de ondas lentas", "Facilita el aprendizaje relacional durante el sueño REM.", "Se estimula por las neuronas orexinérgicas del hipotálamo lateral.", "Inhibe la secreción de GABA en el encéfalo."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 28', 'En relación al tratamiento de la fase maníaca en el trastorno bipolar, ¿cuál de las siguientes afirmaciones es correcta?:', '["En caso de ser necesario prescribir un antipsicótico, se preferirá el uso de antipsicóticos atípicos ya que estos ayudarán a producir un viraje hacia la fase depresiva.", "Se deberá esperar un máximo de 48 horas para determinar los cambios en las concentraciones séricas de litio tras una modificación de dosis.", "La utilización de cualquier benzodiacepina está contraindicada en esta fase del trastorno.", "El tratamiento con ácido valproico se considera una alternativa eficaz en pacientes que no respondan al tratamiento con litio."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 29', 'En relación al tratamiento del trastorno afectivo estacional (TAE), señale la opción FALSA:', '["La fototerapia es más eficaz si es administrada por la mañana.", "La hipersomnia y la avidez por hidratos de carbono son predictores de buena respuesta a la fototerapia.", "La intensidad de la luz en la fototerapia deberá estar siempre por debajo de los 8500 lux.", "Es importante que la luz contenga poca energía del espectro ultravioleta para minimizar los efectos secundarios de la fototerapia."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 30', 'La Terapia interpersonal ha sido ampliamente aplicada en el tratamiento de la depresión. ¿Qué caracteriza a la Terapia Interpersonal?:', '["La terapia interpersonal hace hincapié en detectar pensamientos automáticos interpersonales.", "Enfatiza el papel de las experiencias interpersonales de la niñez.", "Focalizarse en cambiar la personalidad que está generando los conflictos interpersonales.", "Se basa en el modelo médico de la enfermedad depresiva."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 31', 'En un tratamiento psicológico el terapeuta pide al cliente que analice cómo han sido las soluciones que ha venido aplicando a su trastorno hasta el momento. Le pide valorar si se han resultado exitosas, ineficientes, o incluso perjudiciales. Está aplicando:', '["La reconstrucción del estilo afectivo de la terapia constructivista.", "La fase de desesperanza creativa de la terapia de aceptación y compromiso.", "La teoría del guion del análisis transaccional.", "La proyección temporal de la terapia cognitiva."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 32', 'El tratamiento con la Terapia interpersonal (Klerman, Weissman y cols. 1979) se enfoca en resolver las siguientes cuatro áreas de problema interpersonal relacionada con el inicio o mantenimiento del episodio depresivo del paciente:', '["Duelo, disputa de roles, transiciones de roles, déficits interpersonales.", "Duelo, culpa, pérdida, déficits interpersonales.", "Pérdida, conflicto de roles, transición de roles, déficits interpersonales.", "Duelo, culpa, transición de roles, déficits interpersonales."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 33', 'En la terapia cognitiva para las psicosis se propone una evaluación inicial donde se deberían identificar las señales que sirven para disparar las alucinaciones auditivas. Si el terapeuta pide a su cliente que intente avivar y reprimir las voces varias veces al día ¿qué técnica está utilizando?:', '["Autoinstrucciones.", "Evaluación analítica funcional.", "Verbalización concurrente.", "Condicionamiento encubierto."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 34', 'Entre los siguientes posibles efectos secundarios de la clozapina, ¿cuál es el más grave?:', '["Agranulocitosis.", "Sedación.", "Aumento de peso.", "Taquicardia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 36', 'Dentro de las intervenciones psicológicas basadas en internet para personas con psicosis, ¿en qué modelo de terapia se fundamenta el sistema online HORYZONS?:', '["Terapia web de aceptación y compromiso.", "Terapia online \"afrontando voces\".", "Terapia mindfulness basada en la web para alucinaciones auditivas.", "Terapia social online moderada."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 37', '¿Cuál es el primer módulo que se administra cuando se realiza una intervención según la Terapia psicológica integrada para personas con esquizofrenia?:', '["Solución de problemas.", "Diferenciación cognitiva.", "Memoria diferida.", "Entrenamiento en habilidades sociales."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 38', 'Cuando se utilizan técnicas de focalización para el tratamiento cognitivo-conductual de las alucinaciones, la primera fase de intervención consiste en que el paciente:', '["Analice las creencias y pensamientos respecto a las voces.", "Preste atención al contenido de las voces.", "Dirija la atención a la forma y características físicas de las voces.", "Registre los sucesos que acontecen antes de las voces, así como los pensamientos y voces que les siguen."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 39', '¿Qué clase de fármaco es la quetiapina?:', '["Una benzodiacepina.", "Un ansiolítico.", "Un antidepresivo.", "Un antipsicótico."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 40', 'Según Marlatt y Gordon (1985), en el efecto de violación de la abstinencia (EVA) se produce un fenómeno de:', '["Disonancia cognitiva", "Atribución de responsabilidad a factores externos incontrolables.", "Restablecimiento del consumo adictivo hasta sus niveles iniciales.", "Generación de expectativas de resultado positivas."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 41', 'En la técnica del desafío de la Terapia estructural (Minuchin):', '["Se necesita una fuerte alianza terapéutica, por lo que el terapeuta mantiene una posición de cercanía.", "Se busca establecer unos límites rígidos entre los subsistemas familiares para revertir una triangulación de desviación.", "El terapeuta da a escoger entre dos alternativas, una de ellas es una tarea directa y la otra una tarea mucho más onerosa que aquella.", "Es necesario intensificar y repetir el mensaje cuando la inercia de los sistemas familiares les hace resistirse al cambio."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 42', '¿Qué componente se introdujo en las últimas versiones del programa de tratamiento para el control del pánico de Barlow y Craske (2007)?:', '["Re-entrenamiento en respiración.", "Exposición en imaginación.", "Entrenamiento en mindfulness.", "Cuestionamiento de las metapreocupaciones."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 43', 'En el tratamiento para el trastorno de ansiedad social, ¿qué incluye la Terapia cognitivo-conductual en grupo de McEvoy?:', '["Entrenamiento en habilidades sociales.", "Entrenamiento en relajación.", "Retroalimentación en vídeo.", "Biofeedback."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 44', 'En el programa de tratamiento del trastorno de ansiedad generalizada del grupo de Dugas, ¿cuándo se emplea la exposición funcional cognitiva?:', '["Ante preocupaciones que se refieren a acontecimientos basados en la realidad o altamente probables.", "Ante preocupaciones que se refieren a acontecimientos altamente improbables.", "Ante preocupaciones que se refieren a acontecimientos modificables.", "Ante preocupaciones sobre la generación de soluciones alternativas."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 45', 'En el tratamiento cognitivo-conductual del trastorno de ansiedad generalizada, se "enseña" a los pacientes que la preocupación patológica o improductiva consiste en:', '["Pensamientos, imágenes, impulsos o sensaciones físicas desagradables, de carácter intruso, involuntario e indeseado.", "Una cadena de pensamientos sobre problemas inmediatos y realistas, centrada en la resolución de estos o de la situación.", "Pensamientos negativos, autorreferenciales, vinculados habitualmente con eventos del pasado y que aparecen de forma automática.", "Una cadena de pensamientos sobre problemas distales o abstractos, que se centra en la emoción negativa asociada a la situación objeto de preocupación."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 46', 'Andrea, de 35 años de edad, presenta una elevada ansiedad cada vez que nota presión en la cabeza y una leve sensación de mareo, lo que la ha llevado en varias ocasiones al servicio de urgencias por miedo de sufrir un "ictus o un infarto", donde le han descartado organicidad, diagnosticándola de ansiedad y "somatizaciones" y le han pautado ansiolíticos. Desde la primera ocasión, vigila cada vez más su cuerpo, ha evitado hacer ejercicio para no marearse y cada vez que lee o escucha hablar de enfermedades, apaga la TV o sale de la conversación porque refiere que "noto todos los síntomas que escucho, como si los tuviera", de hecho, en la última semana ha ido al médico por notarse los ojos enrojecidos y un dolor fluctuante pero molesto en el costado. A pesar de consultar sus síntomas desconfía de los médicos porque su madre falleció cuando ella tenía 14 años, "porque los médicos no supieron lo que le pasaba". Según la sintomatología de Andrea, ¿qué programa de tratamiento sería el más indicado?:', '["Tratamiento del trastorno de pánico de D. Barlow (2001).", "Tratamiento cognitivo conductual de la somatización de Woolfolk y Allen (2006).", "Tratamiento de la ansiedad por la salud de Warwick y Salkovskis (1990, 2001).", "Tratamiento cognitivo de las ideas delirantes (de tipo somático) de Chadwick (2009)."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 47', '¿Cuál es el componente fundamental de la Terapia cognitiva específica para el tratamiento del trastorno obsesivo-compulsivo (como, por ejemplo, en la propuesta de Belloch et al., 2011)?:', '["La exposición y prevención de respuesta a las situaciones temidas por el paciente.", "La exposición y prevención de respuesta a los contenidos de los pensamientos u obsesiones principales.", "El entrenamiento en técnicas de control de la activación (por ejemplo, relajación).", "El trabajo con las valoraciones y creencias disfuncionales asociadas a las obsesiones."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 48', 'En pacientes con diagnóstico de trastorno obsesivo compulsivo ¿en qué caso estaría más indicado aplicar un componente de exposición con prevención de respuesta?:', '["Paciente con obsesiones de tipo sexual (por ejemplo, prácticas sexuales no deseadas o inmorales).", "Paciente con obsesiones agresivas hacia sí mismo o los otros.", "Paciente con obsesiones sobre la contaminación o suciedad y/o compulsiones de lavado y/o limpieza.", "Paciente con obsesiones blasfemas (por ejemplo, insultar a Dios)."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 49', 'Señale para cuál de los siguientes trastornos está más indicado el entrenamiento en reversión del hábito:', '["Trastorno obsesivo-compulsivo.", "Tricoticolomanía.", "Trastorno de la personalidad obsesivo-compulsivo.", "Trastorno dismórfico corporal."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 50', 'Entre los principios en los que se sustenta la psicoterapia de los trastornos de la personalidad se encuentra el de "gradualidad", que hace referencia a:', '["Promover cambios en los aspectos o manifestaciones que conllevan un mayor nivel de perturbación e interferencia en la vida del paciente, para ir progresando paulatinamente en la mejora de su calidad de vida.", "Establecer una jerarquía de principios y necesidades de cambio y acordar con el paciente la dificultad de cada uno de ellos para ir avanzando en función de ese gradiente.", "Exponerse a las situaciones que provocan malestar, comenzando por las que generan un malestar intermedio.", "Promover cambios en los aspectos o manifestaciones más periféricas del trastorno para ir progresando paulatinamente hacia la consecución de cambios en los patrones más básicos de la organización personal."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 51', 'El tratamiento de los trastornos de la personalidad basado en el modelo de J.E.Young, se basa en:', '["Promover cambios en los esquemas tempranos disfuncionales o desadaptativos (ETD).", "Promover cambios en las conductas que se derivan de los ETD.", "El uso de técnicas experienciales para evocar experiencias infantiles traumáticas.", "Re-elaborar las experiencias de transferencia negativa."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 52', 'La técnica de parada-arranque en la que el paciente estimula su pene hasta conseguir la erección, después se detiene hasta que vuelve al estado de flaccidez y de nuevo vuelve a estimularlo, está indicada ante problemas de:', '["Bajo deseo sexual.", "Aversión al sexo.", "Excitación (en el hombre).", "Anorgasmia."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 53', 'El tratamiento psicológico de trastornos como la depresión, en casos en los que puede ir acompañada de una disfunción sexual, es especialmente importante tratar los problemas que tienen que ver con:', '["Bajo deseo sexual.", "Problemas de excitación.", "Eyaculación precoz.", "Anorgasmia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 54', 'De las siguientes estrategias ¿cuál se dirige a detectar precozmente la existencia de una enfermedad?:', '["Promoción de salud.", "Prevención primaria.", "Prevención secundaria.", "Prevención terciaria."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 55', 'Según el Modelo transteórico del cambio de Prochaska y Di Clemente (1984) ¿en qué fase estaría una persona que evalúa la posibilidad de cambiar?:', '["Precontemplación.", "Contemplación.", "Preparación.", "Acción."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 56', 'El entrenamiento para el uso del peak flow meter forma parte de los programas de automanejo de:', '["El colon irritable.", "El asma.", "La diabetes.", "Los problemas cardiovasculares."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 57', 'En la Terapia de aceptación y compromiso aplicada al dolor crónico, ¿a qué se refiere la fase de "desesperanza creativa"?:', '["A la toma de conciencia de la falta de eficacia que han tenido las estrategias que el paciente ha aplicado hasta el momento para el control del dolor.", "A ayudar al paciente a ver sus pensamientos y sentimientos desde la perspectiva de un observador.", "A enseñar al paciente a identificar los valores importantes de su vida.", "A ayudar al paciente a desarrollar planes de conducta para cambiar su vida."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 58', '¿Para qué tipo de enfermedad se diseñó la Terapia psicológica adyuvante de Moorey y Greer (1989)?:', '["Cáncer.", "VIH.", "Diabetes.", "Fibromialgia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 59', 'Para que se identifique a una persona en el rol de enfermo propuesto por Parsons (1951), ¿cuál de los siguientes requisitos es necesario cumplir?:', '["Mostrar baja adherencia al tratamiento.", "Ser responsable de los síntomas.", "Implicarse en la recuperación de la salud.", "Continuar asumiendo las mismas responsabilidades."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 60', '¿En cuál de las siguientes propuestas teóricas se incluye la intención de conducta como un determinante proximal de la conducta?:', '["Modelo creencias de salud (Rosenstock, 1974).", "Teoría del aprendizaje social (Bandura, 1986).", "Teoría de la acción razonada (Ajzen y Fishbein, 1970).", "Modelo transteórico (Prochaska y Di Clemente, 1984)."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 61', 'J. Frank es uno de los autores más importantes en el estudio de los "factores comunes" en psicoterapia. Señale cuál de los siguientes es uno de los cuatro "factores comunes" que propone como características de todas (o muchas) las formas de psicoterapia (Frank y Frank, 1991):', '["\"Un ritual\" o procedimiento que requiere la participación activa del terapeuta y del cliente.", "Un \"condicionamiento operante\" a través del cual el terapeuta expresa aprobación o desaprobación de la conducta del paciente.", "Una \"regulación conductual\" o \"experiencia correctiva\" basada en la capacidad de sugestión y persuasión del terapeuta.", "\"Factores del terapeuta\" como directividad, empatía, autoridad o aceptación positiva incondicional."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 62', 'La entrevista motivacional (EM), terapia desarrollada en sus orígenes para el tratamiento de las adicciones, ha sido reformulada recientemente por sus autores (Miller y Rollnick, 2013), quienes proponen que son cuatro procesos los que componen la EM; estos son:', '["Vincular, enfocar, evocar y planificar.", "Precontemplación, contemplación, acción y mantenimiento.", "Empatía, discrepancia, discusión y autoeficacia.", "Evaluar, dialogar, escuchar, convencer."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 63', 'Si un psicólogo/a clínico emplea las técnicas de "mindfulness desapegado", "entrenamiento en atención" y "reorientación (o refocalización) de la atención situacional", en qué modelo de psicoterapia se estaría basando:', '["Terapia metacognitiva (Wells).", "Terapia de aceptación y compromiso (Hayes y cols.).", "Psicoterapia analítico funcional (Kholenberg y Tsai).", "Terapia cognitiva basada en mindfulness para la depresión (Segal y cols.)"]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 64', 'Las guías clínicas del Sistema Nacional de Salud (guíasalud.es) establecen 8 niveles de evidencia (de 1++ a 4) y 4 grados de recomendación (de "A" a "D"). ¿Qué grado de recomendación suponen las "opiniones de los expertos" y las "series de casos clínicos"?:', '["Nivel \"B\".", "Nivel \"C\".", "Nivel \"D\".", "No se consideran como evidencia científica, por lo que esos aspectos están excluidos como criterios de cara a la asignación de niveles de recomendación."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 65', 'En un tratamiento psicológico orientado a la superación de miedos, fobias y ansiedad en general, la técnica de modelado más recomendable es:', '["De afrontamiento.", "Asertivo.", "Con reproducción reforzada.", "Competente."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 66', 'Señale cómo se denomina la intervención que consiste en la repetición mental de fórmulas verbales (frases elaboradas) sobre sensaciones psicofisiológicas durante breves periodos de tiempo, además de una concentración pasiva en dichas sensaciones:', '["Autorregulación emocional.", "Entrenamiento autógeno.", "Entrenamiento en autoinstrucciones y respiración.", "Entrenamiento en consciencia plena (mindfulness)."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 67', 'Cuando en la técnica de modelado el modelo muestra conductas evocadoras de ansiedad que no conllevan consecuencias negativas, el terapeuta intenta conseguir:', '["Extinción vicaria.", "Moldeamiento vicario.", "Castigo negativo vicario.", "Modelado negativo."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 68', 'La desensibilización por contacto es una variante de la desensibilización sistemática, en la cual:', '["El terapeuta utiliza instrucciones verbales y guía física para que el cliente realice la exposición con mayor facilidad.", "El terapeuta utiliza, en el proceso de desensibilización, elementos adicionales para favorecer la imaginación de escenas, como fotografías, diapositivas o grabaciones de audio.", "El terapeuta actúa como modelo usando, incluso, el contacto físico con el cliente (sosteniendo la mano del cliente o colocando una mano en su espalda) mientras este realiza la exposición.", "El terapeuta facilita que el cliente realice contacto físico con los estímulos fóbicos (tocándolos con sus propias manos) para así aumentar la eficacia de la exposición."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 70', 'La Desensibilización y reprocesamiento por movimientos oculares (EMDR) en su aplicación a niños:', '["Consta de 8 fases, igual que en adultos.", "Sólo utiliza la fase de desensibilización o reprocesamiento.", "Reduce las 8 fases a cuatro.", "Prescinde de la intervención sobre aspectos cognitivos."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 71', 'Las escenificaciones emotivas, como procedimiento de tratamiento de la ansiedad en niños, constan de:', '["Tres componentes: exposición en vivo, modelado participante y práctica reforzada.", "Tres componentes: terapia de juego, exposición en vivo y reforzamiento diferencial.", "Un componente fundamental basado en la exposición con prevención de respuesta.", "Tres componentes: desensibilización, reforzamiento diferencial y moldeamiento."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 72', 'El tratamiento conductual de la encopresis funcional (por ejemplo, Bragado, 2001):', '["Se basa fundamentalmente en los principios del comportamiento clásico.", "Se basa fundamentalmente en los principios del condicionamiento operante.", "Se basa, fundamentalmente, en los principios del biofeedback.", "No existe un tratamiento exclusivamente conductual de la encopresis funcional."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 73', 'La técnica de Inversión del hábito (Azrin y Nunn):', '["Ha demostrado su eficacia en los trastornos por tics en niños, tanto a corto como a largo plazo.", "No es una técnica psicológica eficaz, ya que tiende a incrementar los tics a largo plazo.", "Está indicada en el tratamiento del trastorno obsesivo compulsivo infantil.", "Se basa fundamentalmente en la relajación de Jacobson."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 74', '¿Cuál de las siguientes técnicas está dirigida a trabajar las conductas impulsivas en niños?:', '["Técnica del árbol.", "Técnica de la alfombra mágica.", "Técnica del águila.", "Técnica de la tortuga."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 75', 'Según el modelo A-B-C en terapia cognitiva aplicada a niños y adolescentes y teniendo en cuenta los estadios evolutivos postulados por Piaget, señala la opción correcta:', '["La terapia cognitiva no es aplicable a niños en el estadio de operaciones concretas.", "La terapia cognitiva no es aplicable a niños en el estadio de operaciones formales.", "La terapia cognitiva no es aplicable a niños en el estadio preoperativo.", "La terapia cognitiva no es aplicable en los estadios preoperativos y de operaciones concretas, pero sí en el estadio de operaciones formales."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 76', 'En el tratamiento de la ansiedad por separación y ansiedad generalizada en la infancia, para poder aplicar la técnica de relajación progresiva, Cautela y Groden (1989) señalan unas habilidades mínimas para realizar los ejercicios de relajación. Entre estas se encuentran:', '["Permanecer quieto durante cinco segundos.", "Mantener el contacto ocular durante diez segundos.", "Cumplir instrucciones complejas.", "Imitación de habilidades motoras complejas."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 77', 'Señale la respuesta correcta con respecto al programa ACCIÓN (Stark y cols., 2010) para el tratamiento grupal de la depresión mayor:', '["La población diana son adolescentes de entre 13 y 18 años.", "Utiliza planificación de actividades placenteras y de dominio y el entrenamiento en habilidades de autocontrol de la ira.", "No tiene en cuenta el uso de técnicas de reestructuración cognitiva adaptadas a niños.", "Las habilidades de solución de problemas no forman parte del programa."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 78', 'En la Hipótesis de la coerción (Patterson, 1982), cuando el padre retira la orden por no oír llorar o gritar al niño porque no obedece, el mantenimiento de la conducta coercitiva se explica por:', '["Refuerzo positivo.", "Refuerzo negativo.", "Castigo positivo.", "Castigo negativo."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 79', '"Imagina que eres un gato que se despereza, estirando sus patas y arqueando el lomo". ¿A qué corresponde esta instrucción?:', '["Ésta es una instrucción que forma parte del entrenamiento en respiración profunda, para el control de la activación fisiológica excesiva en niños.", "Forma parte del entrenamiento en autoinstrucciones (Meichembaum y Goodman, 1971).", "Forma parte de las instrucciones del entrenamiento en relajación de Koeppen (1974), una variante de la relajación progresiva.", "Forma parte de las autoinstrucciones utilizadas en el programa Coping Cat de Kendall (1990)."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 80', '¿Cuál de los siguientes NO es un programa de tratamiento para el trastorno de ansiedad generalizada en la infancia?:', '["El programa de tratamiento Coping Cat.", "El programa FRIENDS.", "El programa Coping Bear.", "El programa de intervención de Herbert."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 81', 'Los delirios en los niños:', '["Son más frecuentes que en los adultos.", "Tienden a ser muy sistematizados.", "Son, habitualmente, de tipo persecutorio, grandeza o hipocondría.", "No se dan delirios en los niños sólo ideas sobrevaloradas."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 82', 'Según el DSM 5, señale a partir de qué características pueden diferenciarse, en niños pequeños, el Trastorno de apego reactivo del Trastorno del espectro autista:', '["Analizar los síntomas nucleares que presenta ya que no hay semejanzas entre un trastorno y otro.", "La historia de cuidados previos al desarrollo del trastorno, así como observar la presencia de comportamientos repetitivos e intereses restringidos.", "La manifestación de expresiones inhibidas de las emociones positivas.", "La presencia de retraso cognitivo del lenguaje y de alteraciones de la reciprocidad social."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 83', 'Señale cuál de los siguientes elementos no está presente en el programa para el tratamiento de las adicciones comportamentales de Echeburúa (Echeburúa y cols., 2005 y Echeburúa, 2009):', '["Análisis de los estímulos asociados a la adicción.", "Control de estímulos asociados a la adicción.", "Atención plena a los estímulos asociados a la adicción.", "Exposición a estímulos asociados a la adicción."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 84', '¿En la infancia, las parasomnias se consideran?:', '["Trastornos secundarios del sueño, e incluyen narcolepsia, terrores nocturnos y sonambulismo.", "Trastornos primarios del sueño, e incluyen pesadillas, terrores nocturnos y sonambulismo.", "Trastornos del sueño y de la motricidad, e incluyen síndrome de piernas inquietas y sonambulismo.", "Un tipo de insomnio que incluye la apnea obstructiva y las pesadillas."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 85', 'Una niña de 9 años se caracteriza por presentar fuertes y muy frecuentes agresiones verbales y arrebatos agresivos físicos esporádicos (pero más de 2 al mes), que producen destrucción de propiedades, daño a personas y animales, que no son premeditados, y suelen durar unos 20 o 30 minutos, echándole la culpa siempre a lo que ocurre a su alrededor, no existiendo un periodo previo prodrómico. ¿Cuál de los siguientes trastornos podría presentar?:', '["Trastorno por déficit de atención e hiperactividad, y se podría diagnosticar también trastorno de conducta.", "Trastorno explosivo intermitente.", "Trastorno de desregulación disruptiva del estado de ánimo, siempre que se acompañe de periodos estables de bienestar y euforia.", "Trastorno bipolar de inicio en la infancia."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 86', 'Un niño de 8 años presenta accesos de cólera frecuentes, de tres a cuatro por semana, rompe cosas y se enfada mucho, está irritado en general, y estas características son más frecuentes en casa, aunque típicas también en el colegio. ¿Qué trastorno presenta?:', '["Trastorno depresivo mayor.", "Trastorno bipolar.", "Trastorno explosivo intermitente.", "Trastorno de desregulación disruptiva del estado de ánimo."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 87', 'A partir de qué edad mínima (aproximada) es fiable la recogida de información mediante autoinformes en los niños:', '["5 años.", "7 años.", "10 años.", "12 años."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 88', 'Respecto a las técnicas de registro de la conducta de un sujeto al que estamos observando, ¿qué características tiene el registro narrativo?:', '["Es la técnica de registro observacional que permite un mayor rigor científico respecto a las demás técnicas.", "Está dirigido a evaluar las interacciones que se producen entre el ambiente y la conducta, o entre un individuo y un grupo.", "Consisten en realizar descripciones de lo observado sin existir una estructuración previa que dirija la recogida de datos.", "Se basan en técnicas escalares y sirven para clasificar las actividades de un sujeto según dimensiones previamente establecidas."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 89', 'Cuando estamos evaluando la conducta de un sujeto a través de la observación, ¿qué se recomienda para reducir el sesgo de reactividad?:', '["Maximizar la interacción entre sujeto y observador para que el sujeto se sienta más cómodo cuando es observado.", "Utilizar un amplio periodo de observación para que el sujeto se habitúe a la situación de observación.", "Utilizar un único observador para que la recogida de datos sea más homogénea.", "No utilizar dispositivos ocultos o a distancia que podrían disminuir la validez ecológica de la observación."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 90', '¿Cuál de las siguientes es una técnica de evaluación proyectiva?:', '["El Diferencial semántico de Osgood.", "El Test de aptitudes perceptivas.", "La Técnica de la rejilla.", "El Test de apercepción temática de Murray."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 91', 'En las Escalas de inteligencia de Wechsler para adultos (WAIS-III, WAIS-IV), ¿cuáles de estas escalas forman parte del Índice de memoria de trabajo?:', '["Clave de números y Búsqueda de Símbolos.", "Vocabulario y Semejanzas.", "Aritmética y Dígitos.", "Cubos y Matrices."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 92', 'Los test psicométricos se pueden clasificar en test de rendimiento máximo y test de rendimiento típico según la demanda que se le hace al sujeto. ¿En qué consiste un test de rendimiento típico?:', '["El sujeto tiene que escoger la única respuesta verdadera entre una serie de alternativas.", "Se trata de valorar el rendimiento más alto de una persona en un constructo determinado como, por ejemplo, la inteligencia.", "El objetivo principal es valorar la cantidad de ítems que resuelve la persona en un tiempo limitado.", "El objetivo es valorar la manera habitual de comportarse de un individuo."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 93', 'Las Escalas McCarthy de aptitudes y psicomotricidad para niños (MSCA):', '["Evalúan las aptitudes del niño a través de dos escalas principales: la de procesamiento secuencial y la de procesamiento simultáneo.", "Son adecuadas para evaluar a niños muy pequeños y con dificultades de aprendizaje.", "Se utilizan para valorar la inteligencia desde la perspectiva de la evaluación dinámica, es decir, evalúan el potencial de aprendizaje del niño.", "Son útiles para valorar la motricidad y las aptitudes de niños con inteligencia dentro de la media, ya que son poco sensibles para evaluar a niños con retraso intelectual."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 94', 'La evaluación de la personalidad se ha hecho desde diversos modelos y teorías. Desde las teorías factoriales, el test más representativo que ha inspirado el desarrollo de otros, es:', '["Minnesota multiphasic personality inventory, (MMPI).", "Sixteen personality factor questionnaire, (16PF).", "Gordon personal profile (GPP).", "Tennessee Self Concept Scale (TSCS)."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 95', '¿Qué instrumento para la medida de la inteligencia se diseñó para evaluar el factor "g" tal y como fue definido por Spearman?:', '["Escalas de inteligencia de Weschler.", "Escala de inteligencia de Stanford-Binet.", "Escalas de capacidad diferencial.", "Test de matrices progresivas de Raven."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 96', 'La Entrevista diagnóstica DIS (Diagnostic Interview Schedule), que proporciona información sobre el inicio, duración y actualidad de los síntomas, es un ejemplo de entrevista:', '["Estructurada.", "Semiestructurada.", "Motivacional.", "Abierta."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 97', '¿Qué tipo de técnica proyectiva es el test "Dibujo de la figura humana"?:', '["Estructural.", "Temática.", "Constructiva.", "Expresiva."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 98', 'Cuando el comportamiento a observar es no discreto y por tanto resulta difícil determinar cuándo empieza y cuándo acaba, el método de medición más útil es el método de intervalos, por ejemplo, el muestreo de intervalo completo o total. En este muestreo:', '["Se requiere que la conducta aparezca al menos una vez a lo largo del intervalo.", "Se registra la conducta que ocurre en el momento en el que termina el intervalo.", "La conducta no se registra si no se produce durante la totalidad del intervalo de observación establecido.", "Se registra la frecuencia de las conductas que aparecen durante el intervalo."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 99', 'Respecto a la evaluación de la inteligencia infantil, ¿qué prueba permite medir la inteligencia general según dos subescalas: verbal y no verbal?:', '["El K-Bit de Kaufman.", "Las Escalas McCarthy (MSCA).", "El TONI-2.", "El K-ABC de Kaufman."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 100', 'Entre las técnicas de entrevista verbal no directivas se encuentra:', '["La proxemia.", "La paráfrasis.", "La Kinesia.", "La sincronía."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 101', 'En general, la evaluación dinámica del potencial de aprendizaje es apropiada para determinar el tratamiento en casos de:', '["Sujetos de bajo nivel cognitivo.", "Sujetos que presentan rendimiento académico adecuado.", "Sujetos con dificultades para aprendizajes generales.", "En aquellos casos en que sea preciso clarificar los procesos automáticos implícitos en los aprendizajes."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 102', 'En las Escalas de Inteligencia de Wechsler para adultos (WAIS-III y WAIS-IV), ¿de qué índice forma parte la prueba "Clave de números"?:', '["Memoria de trabajo.", "Comprensión verbal.", "Velocidad de procesamiento.", "Organización perceptiva."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 103', '¿Qué tipo de técnica proyectiva es el Test del Árbol de Koch?:', '["Asociativa.", "Catártica.", "Expresiva.", "Estructural."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 104', 'Atendiendo a la "finalidad" de la entrevista, y en relación a la entrevista consultiva:', '["Suele tener un objetivo focal, con una finalidad muy concreta, en la que el entrevistado no va a proseguir con un trabajo clínico posterior.", "Tiene un objetivo no terapéutico y de consejo.", "Está orientada a establecer un diagnóstico en un paciente.", "Tiene por finalidad operar un cambio en una dirección acordada por ambos, entrevistador y entrevistado."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 105', '¿Qué nivel de muestreo intrasesional estamos utilizando si en una sesión de clase se muestrea cada 30 segundos a un alumno para ver si se mantiene en la posición correcta?:', '["Continúo de toda la sesión.", "De eventos.", "Temporal.", "Focal."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 106', 'Desde los "sistemas de expertos", propiciados por el desarrollo de la Inteligencia artificial, se han creado programas destinados a:', '["Desarrollar baterías neuropsicológicas.", "La construcción de test adaptativos informatizados.", "La utilización de la \"realidad virtual\".", "Emular el proceso que sigue el clínico en la evaluación para producir conclusiones diagnósticas."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 107', 'Cuando se aplica la escala de inteligencia Wechsler (WPPSI-IV) en niños menores de cuatro años se incluye:', '["Test de dibujos.", "Aritmética.", "Búsqueda de animales.", "Test de semejanzas."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 108', 'En la evaluación psicofisiológica de la actividad electrodérmica, los parámetros más frecuentes para medir la conductancia de la piel son la amplitud de respuesta y:', '["El periodo de recuperación", "El tiempo de latencia", "La resistencia", "La variabilidad de la respuesta a lo largo de todo el proceso de medida."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 109', '¿Qué factor de riesgo temperamental se relaciona con el trastorno obsesivo compulsivo (DSM-5)?:', '["Extraversión.", "Reducida emotividad positiva.", "Comportamiento perturbador.", "Síntomas de interiorización."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 110', 'Respecto de los criterios diagnósticos para el trastorno de ansiedad generalizada, el DSM-5 establece como duración mínima de los síntomas nucleares (señale la respuesta correcta):', '["Dos semanas.", "Un mes.", "Tres meses", "Seis meses."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 111', 'Respecto del Trastorno obsesivo compulsivo (TOC), cabe afirmar lo siguiente:', '["Los varones presentan una edad más temprana de inicio de los síntomas del trastorno que las mujeres.", "En general, los estudios muestran que la prevalencia a lo largo de la vida es del 3-4 %.", "La presencia de TOC no es universal.", "El TOC suele comenzar en la infancia."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 112', 'Señale la afirmación correcta respecto de los terrores nocturnos:', '["Generalmente se producen en el último tercio del periodo principal del sueño", "Es una parasomnia del sueño REM.", "Forman parte, junto con el sonambulismo, de una misma categoría diagnóstica (DSM 5).", "Suele recordarse el contenido de lo soñado en gran medida."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 113', 'El diagnóstico de la narcolepsia, aunque esencialmente clínico, idealmente debe ser confirmado en laboratorio de sueño a través de:', '["Poligrafía de sueño seguida de tonometría a la mañana siguiente.", "Poligrafía de sueño seguida del Test de Romberg a la mañana siguiente.", "Polisomnografía nocturna, seguida a la mañana siguiente del test de latencias múltiples de sueño (TLMS).", "Polisomnografía nocturna, seguida a la mañana siguiente de capnografía."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 115', 'En el síndrome de la apnea/hipopnea obstructiva del sueño (SAHOS) moderado a grave, con sintomatología (somnolencia/diurna) el tratamiento de elección es:', '["Un fármaco hipnótico.", "Un fármaco ansiolítico.", "La presión positiva continua en la vía aérea.", "El neurofeedback."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 116', 'Señale cuál de los siguientes fenómenos es menos propio y definitorio del trastorno de identidad disociativo (DSM 5):', '["Experiencias de distanciamiento e irrealidad respecto al entorno.", "Vacíos recurrentes al recordar eventos cotidianos.", "Seria discontinuidad en el sentido de identidad.", "Alteraciones en el afecto, conducta, conciencia y memoria."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 117', '¿Cuál de los siguientes síntomas conductuales es más característico de la amnesia disociativa?:', '["Comportamiento mecánico.", "Analgesia.", "Autolesiones e intentos de suicidio.", "Macropsia o micropsia."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 118', '¿Cuál es el principal sesgo cognitivo del jugador patológico?:', '["La ilusión de control.", "La negación y la mentira.", "Evaluación sesgada de los resultados.", "La idea de que cuanto más se juega hay más posibilidades de ganar."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 119', '¿Cuáles son los principales efectos de las anfetaminas?:', '["Elevación del estado de ánimo y disminución de la sensación de fatiga y del apetito.", "Después de los iniciales efectos eufóricos en poco tiempo le sigue un claro síndrome amotivacional junto con supresión del sueño normal durante semanas.", "El consumo produce un sueño excesivo.", "Estado de completo bienestar, euforia, sensación de flotar y desaparición de las inhibiciones."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 120', '¿Cuál de las siguientes drogas produce una fuerte dependencia psicológica pero poca dependencia física:', '["La cafeína.", "El alcohol.", "La cocaína.", "La heroína."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 121', 'De las drogas existentes, el consumo regular de heroína y morfina se caracteriza porque:', '["Desarrollan rápidamente tolerancia y dependencia en los consumidores.", "Los daños en la salud sólo se producen a largo plazo.", "Producen una fuerte dependencia física pero no psicológica.", "Producen un característico estado amotivacional en sus consumidores."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 122', 'La capacidad que tiene una sustancia de producir dependencia en los que la consumen, recibe el nombre de:', '["Dependencia física.", "Dependencia psicológica.", "Aumento de la tolerancia.", "Potencial adictivo de una droga."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 123', '¿Cuál NO sería una característica de buen pronóstico en el Trastorno esquizofreniforme:', '["Aparición de síntomas psicóticos notables dentro de las primeras cuatro semanas.", "Confusión o perplejidad.", "Que el episodio se desencadene con un episodio maniaco.", "Ausencia de afecto aplanado o embotado."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 124', '¿Cómo se denomina al fenómeno por el que a una palabra existente se le da un significado diferente al que en realidad tiene?:', '["Neologismo.", "Palilalia.", "Paralogismo.", "Glosolalia."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 125', '¿Cómo se denomina al fenómeno que ocurre si un paciente está convencido de que otra persona ha sido transformada físicamente en sí mismo?:', '["Síndrome de intermetamorfosis.", "Delirio de los dobles.", "Síndrome de Fregolí.", "Síndrome de los dobles subjetivos."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 126', '¿Cuál de las siguientes respuestas es correcta con respecto al trastorno facticio?:', '["No hay comportamiento engañoso-fingimiento si no existe incentivo externo.", "La producción de los síntomas no es intencionada.", "Lo habitual es que curse en forma de episodios intermitentes.", "En el trastorno facticio aplicado a otro, el diagnóstico se aplica tanto al autor como a la víctima."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 127', '¿Cuál de las siguientes respuestas es correcta con respecto a la bulimia nerviosa?:', '["Es más prevalente en mujeres jóvenes que la anorexia nerviosa.", "Los atracones deben ocurrir, al menos, tres veces a la semana, cuatro meses seguidos, para poder diagnosticar el trastorno.", "A diferencia de lo que ocurre en la anorexia nerviosa, el peso corporal no influye indebidamente en la autoevaluación de la persona.", "Los atracones suelen ser de alimentos que también consumen, normalmente, entre episodios."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 128', 'Ante la sospecha de presencia de depresión en una persona ¿cuál de los siguientes aspectos relacionados con el diagnóstico habría que abordar antes?:', '["La existencia de una etiología médica u orgánica.", "La posible comorbilidad con trastornos de ansiedad.", "La especificación de las distorsiones cognitivas presentes en el caso.", "La realización del análisis funcional para la explicación del origen y mantenimiento del trastorno."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 129', 'Según la Teoría de los estilos de respuesta (Nolen-Hoksema), el elemento fundamental para la consolidación de un trastorno depresivo sería:', '["La vivencia de acontecimientos de pérdida.", "La limitación en las capacidades de afrontamiento de esas pérdidas.", "La baja autoestima.", "Las respuestas rumiativas."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 130', 'Según el DSM-5, ¿cuál de las siguientes es una característica definitoria de los trastornos depresivos melancólicos durante la fase más grave del episodio actual?:', '["Reactividad o aumento del estado de ánimo en respuesta a sucesos positivos reales o potenciales.", "Pérdida de placer por todas o casi todas las actividades.", "Aparición y remisión de episodios depresivos en determinadas épocas del año.", "Sensación de nervios o tensión."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 131', 'Según la hipótesis permisiva de la depresión:', '["El déficit en la neurotransmisión serotoninérgica lleva a la aparición de la depresión.", "El incremento en la neurotransmisión serotoninérgica lleva a la aparición de la depresión.", "El déficit en la neurotransmisión serotoninérgica predispone a la aparición de la depresión, presentándose el estado depresivo si hay además un déficit en la neurotransmisión catecolaminérgica.", "El déficit en la neurotransmisión serotoninérgica predispone a la aparición de la depresión, presentándose el estado depresivo si hay además un incremento en la neurotransmisión catecolaminérgica."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 132', 'Según el DSM-5, el trastorno de estrés postraumático se especifica cómo "con expresión retardada" cuando:', '["No va precedido de un trastorno de estrés agudo.", "El inicio de los primeros síntomas se produce al menos un mes después del acontecimiento traumático.", "El inicio de los primeros síntomas se produce al menos seis meses después del acontecimiento traumático.", "La totalidad de criterios diagnósticos no se cumplen hasta al menos seis meses después del acontecimiento traumático."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 133', 'Respecto de las imágenes alucinoides, cabe afirmar que:', '["Se producen en ausencia de estímulos concretos que las activen.", "El individuo les otorga juicio de realidad.", "Se trata de un concepto sinónimo al de imagen eidética.", "Son un tipo de imagen mnémica."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 135', 'La Teoría del procesamiento de la información aplicada al trastorno de estrés postraumático se centra en la explicación de:', '["La reexperimentación del acontecimiento traumático.", "Las conductas de evitación de los estímulos que recuerdan al trauma", "Los problemas afectivos, la pérdida de interés y la apatía.", "La hiperactividad y la ansiedad extrema."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 136', 'Señale la afirmación correcta con respecto a las tasas de suicidio en relación con los trastornos del estado de ánimo:', '["Son mayores en depresión mayor que en trastorno bipolar.", "Son similares en depresión mayor y en trastorno bipolar.", "Son mayores en trastorno bipolar que en depresión mayor.", "Los datos provienen de estudios que no permiten afirmar nada al respecto."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 137', 'Según el DSM 5, una persona con un familiar de primer grado con una fobia específica a los animales es significativamente más propensa a tener:', '["La misma fobia específica.", "Cualquier otra fobia específica.", "Cualquier otra fobia.", "Cualquier otro trastorno de ansiedad."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 138', '¿Cuál es la duración mínima necesaria para poder realizar un diagnóstico de mutismo selectivo según DSM 5?:', '["Un mes.", "Tres meses.", "Seis meses.", "Doce meses."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 139', 'Señale cuál de las siguientes afirmaciones sobre el trastorno de ansiedad por separación es FALSA:', '["Se desarrolla con frecuencia después de un estrés vital (p. ej., la muerte de una mascota familiar).", "Puede ser hereditario.", "Los niños manifiestan una mayor reticencia a asistir a la escuela que las niñas.", "La expresión indirecta del miedo a la separación puede ser más común en los varones."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 140', 'Las falsificaciones del recuerdo que aparecen en un estado de lucidez de conciencia asociadas a una amnesia orgánica y sin que el paciente tenga la intención de mentir se denomina:', '["Pseudologías o seudologías fantásticas.", "Falsos reconocimientos.", "Confabulaciones.", "Paramnesias reduplicativas."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 141', 'Un paciente que tiene una vívida sensación de que sus venas se están enrollando sobre sí mismas está experimentando una:', '["Alucinación cenestésica.", "Parestesia.", "Alucinación vascular.", "Alucinación táctil."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 142', '¿Cómo se denominan las imágenes anómalas que se pueden percibir en los momentos de transición de la vigilia al sueño:', '["Imágenes hipnopómpicas.", "Imágenes mnémicas.", "Imágenes hipnagógicas.", "Imágenes parásitas."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 143', '¿Cómo se denomina la utilización o creación de palabras raras cuyo significado sólo conoce el individuo?:', '["Asintaxia.", "Aproximación de palabras.", "Neologísmos", "Alexia."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 144', '¿Cómo se denomina la dificultad de la articulación y expresión de palabras producida por lesiones en el sistema nervioso?:', '["Afasia.", "Dislalia.", "Disglosia.", "Disartria."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 145', 'La afirmación "la presentadora de televisión me quiere avisar de que corro un grave peligro y por eso se ha puesto un vestido verde" es un ejemplo de:', '["Temple o humor delirante.", "Ocurrencia delirante.", "Percepción delirante.", "Representación delirante."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 146', '¿Cuál de las siguientes alteraciones se considera una distorsión perceptiva?:', '["Dismorfopsia.", "Imagen hipnagógica.", "Pseudoalucinación.", "Imagen autoscópica."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 147', 'Cuando una experiencia perceptiva se mantiene y/o se activa a pesar de que el estímulo inicial que la produjo ya no se encuentra accesible a los órganos sensoriales, es muy probable que se experimente:', '["Una pareidolia.", "Una alucinación refleja.", "Una imagen parásita.", "Una pseudoalucinación visual."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 148', '¿Cómo se llama la alteración del pensamiento en el que el paciente para de hablar a mitad de la frase y cambia de tema en respuesta a estímulos cercanos (por ejemplo, la corbata del entrevistador)?:', '["Presión del habla.", "Tangencialidad.", "Circunstancialidad.", "Habla distraída."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 149', 'La flexibilidad cerea, el negativismo o la catalepsia –que pueden estar presentes como síntomas de catatonia según DSM 5- se manifiestan:', '["Cuando el paciente es inducido a realizar ciertas acciones o movimientos.", "Cuando el paciente decide realizar un movimiento voluntario, ya que estos síntomas están bajo su control voluntario.", "Cuando el paciente realiza un movimiento involuntario.", "Cuando el paciente está en reposo."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 150', '¿Cuál de estas perturbaciones de la memoria constituye, más propiamente, una paramnesia del recuerdo?:', '["Agnosia.", "Confabulación.", "Amnesia reduplicativa.", "Criptomnesia."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 151', 'En cuanto a la incidencia del trastorno de la personalidad obsesivo-compulsivo en población general:', '["Se da más en mujeres que en hombres.", "Se da más en hombres que en mujeres.", "Se ha constatado que es coincidente entre hombres y mujeres.", "Las debilidades metodológicas de los estudios no permiten conclusiones fiables en este sentido."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 152', 'Señale cuál de las siguientes anomalías neuroanatómicas o neurofisiológicas NO es propia de la esquizofrenia:', '["Disminución de surcos corticales.", "Disminución del volumen del tálamo.", "Disminución de lóbulos frontales y temporales.", "Disminución en el metabolismo de la glucosa en lóbulos frontales."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 153', 'Señale la afirmación correcta respecto al trastorno narcisista de la personalidad:', '["Su presencia en población general es menor del 1% (DSM 5).", "Su presencia en población clínica es del 7 al 15 % (DSM 5).", "La mayor comorbilidad se da con las parafilias y las disfunciones sexuales.", "Los factores genéticos parecen explicar el mayor porcentaje de varianza del trastorno."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 154', 'Respecto del trastorno de despersonalización cabe afirmar que:', '["La duración de los \"episodios\" es siempre breve (no persistentes).", "El curso del \"trastorno\" es usualmente episódico, no crónico.", "Entre sus características clínicas figuran las rumiaciones obsesivas y preocupaciones somáticas.", "En el transcurso del trastorno se alteran las pruebas de realidad."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 155', 'Respecto del trastorno obsesivo compulsivo (TOC), señale la opción correcta:', '["Los niños están menos afectados que las niñas.", "La remisión espontánea es muy alta.", "En comparación con trastornos de ansiedad y depresión, los pacientes con TOC tienen mayor probabilidad de ser solteros y estar en paro.", "El comienzo suele ser brusco/súbito como respuesta a situaciones de estrés."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 156', 'Alguna de las limitaciones de la Teoría clásica de los test frente a la Teoría de respuesta al item vienen por:', '["La menos fiabilidad de los instrumentos y la mayor complejidad matemática de los modelos antiguos.", "La ausencia de invarianza y la consideración de un nivel de precisión uniforme.", "La ausencia de invarianza y la ausencia de validez predictiva.", "El grado de dificultad de los ítems y la menor validez de contenido."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 157', 'La fórmula de Spearman-Brown se usa para estimar el cambio en el coeficiente de fiabilidad de un test que se produce cuando aumenta:', '["La variabilidad de una nueva muestra en que se analiza el test.", "La longitud de un test añadiendo ítems paralelos al del test original.", "El tamaño de una nueva muestra en que se analiza el test.", "La dificultad de los ítems en una nueva versión del test."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 158', 'Para interpretar adecuadamente los resultados obtenidos mediante un análisis factorial de la varianza debe tenerse en cuenta (indique la afirmación INCORRECTA):', '["Cuando el efecto de interacción es estadísticamente significativo, el interés de los efectos principales se reducen en cierta medida dado que su interpretación depende de los niveles del resto de factores.", "El análisis de los efectos simples implica interpretar el efecto de un factor cuando se tiene en cuenta un único nivel de otro factor.", "El análisis de los efectos simples sólo tiene sentido cuando la interacción entre los factores es estadísticamente significativa.", "El efecto de interacción solo será estadísticamente significativo si los efectos principales también lo son."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 159', 'En el ámbito del análisis estadístico, en concreto de la regresión lineal, indique la afirmación INCORRECTA:', '["La regresión lineal permite analizar la relación entre uno o más predictores cuantitativos y una variable dependiente también cuantitativa, no pudiéndose en ningún caso incluir en el análisis predictores categóricos.", "En el análisis de regresión, el coeficiente de regresión parcial no estandarizado Bo ó β0 ofrece el valor de la ecuación de regresión cuando todos los predictores son igual a cero.", "Una estrategia para medir la bondad de ajuste en un análisis de regresión simple es utilizar el coeficiente de determinación que se calcula elevando al cuadrado el coeficiente de correlación de Pearson.", "Si se desea encontrar la ecuación de regresión capaz de ofrecer el mejor ajuste posible con el menos número de variables, se recomienda utilizar la regresión jerárquica o por pasos."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 160', 'En el marco del análisis de la varianza, con un factor y tres tratamientos, indique la afirmación INCORRECTA:', '["La prueba de Dunn-Bonferroni nos permitiría llevar a cabo comparaciones múltiples entre pares de medias planificadas o a priori.", "Si el investigador desea realizar todas las posibles comparaciones por pares, post hoc o a posteriori, podía utilizar la prueba de Tukey.", "Para estimar el tamaño del efecto relativo a la proporción de varianza explicada, sería aconsejable la utilización de eta-cuadrado (η²), por ser un estimador no sesgado.", "En el caso de incumplir el supuesto de homogeneidad de las varianzas se recomienda utilizar los estadísticos W de Welch o F de Brown y Forsythe, como alternativa al estadístico F."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 161', 'Un investigador desea analizar el impacto de una intervención para mejorar las capacidades de lecto-escritura. Para ello, antes de aplicar la intervención mide la capacidad de lecto-escritura en la muestra y establece un punto de corte. Los sujetos con puntuaciones por encima del punto de corte constituirán el grupo de control y aquéllos por debajo del punto de corte recibirán la intervención (grupo experimental). Tras la intervención, el investigador medirá nuevamente la capacidad en lecto-escritura de todos los sujetos. Según este enunciado, señale la opción INCORRECTA:', '["Se ha utilizado una regla de asignación no aleatoria pero conocida.", "Se trata de un diseño de discontinuidad en la regresión.", "Se trata de un diseño con grupo de control no equivalente.", "Se ha utilizado un diseño cuasi-experimental pretest-postest con grupo de control."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 162', 'En relación con los diseños de investigación en Psicología, indique cuál de las siguientes afirmaciones es INCORRECTA:', '["El diseño de bloques tiene como objetivo, entre otros, el análisis de la interacción entre la variable de tratamiento y la variable de bloqueo.", "El diseño de cuatro grupos de Solomon permite analizar el posible efecto de sensibilización del pretest, en el efecto del tratamiento.", "En los diseños de medidas repetidas, el principal problema es el derivado de la secuencialidad en la que se aplican los tratamientos.", "Los diseños experimentales de covarianza tienen como objetivo la reducción de la varianza de error, incluyendo variables cuantitativas como covariables."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 163', 'En lo que respecta a la validez de conclusión estadística, indique cuál de las siguientes afirmaciones es correcta:', '["La potencia es complementaria al error de tipo I y se define como la capacidad de una prueba estadística para detectar una relación entre variables.", "El error de tipo II se refiere al hecho de detectar una relación entre variables cuando de hecho no existe tal relación en la población.", "La probabilidad de cometer un error de tipo I se denomina alpha y se refiere a rechazar la hipótesis nula cuando dicha hipótesis es verdadera.", "El tamaño muestral tiene una relación inversamente proporcional con la potencia de la prueba estadística."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 164', 'El modelo de condicionamiento de la tolerancia a las drogas atribuye la tolerancia:', '["Al efecto compensatorio de la homeostasis.", "A la sobreexposición al estímulo incondicionado (droga) que produce extinción del placer asociado.", "Al contracondicionamiento de las influencias positivas del entorno familiar y social para que se deje la droga.", "A las respuestas condicionadas a los estímulos del entorno que se asocian con la administración de la droga."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 165', 'En la tarea de seguimiento (sombreado) ideada por Cherry (1953) se utilizó la escucha dicótica y se presentaron dos mensajes uno por cada oído. El participante debía repetir palabra por palabra el mensaje del oído atendido. Cuando se preguntó por el mensaje ignorado (no atendido) los participantes detectaron:', '["El cambio de idioma.", "El significado del mensaje.", "La relación semántica entre el mensaje atendido y no atendido.", "El cambio de voz del hablante."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 166', '¿Qué dos condiciones o pistas (señales) se utilizan en el Test de las redes atencionales (Attentional Network Test, ANT), para calcular la puntuación correspondiente a la red de orientación?:', '["La pista (señal) central, y la pista (señal) espacial o periférica.", "La pista (señal) central, y la doble pista (señal).", "La pista (señal) doble, y la no pista (no señal).", "La no pista (no señal), y la pista (señal) espacial o periférica."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 167', 'De acuerdo con los estudios de Tulving y otros autores sobre la recuperación de información de la memoria, ¿qué claves de recuperación son las más eficaces para recuperar un determinado contenido de la memoria episódica?:', '["Las claves que están más fuertemente relacionadas semánticamente con el contenido que queremos recuperar.", "Las claves que, además de al contenido que queremos recuperar, están asociadas a más contenidos diferentes de nuestra memoria episódica.", "Las claves a las que se presta menos atención durante la recuperación.", "Las claves que estuvieron presentes durante la codificación y fueron codificadas junto con el contenido que ahora queremos recuperar."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 168', 'Según el modelo de covariación de Kelley ¿Qué tipos de información utilizan los sujetos para realizar atribuciones sobre las causas de la conducta de otra persona?:', '["Locus externo/interno, estabilidad y controlabilidad.", "Coherencia/consistencia, distintividad y consenso.", "Efectos no comunes, relevancia hedónica y personalismo.", "Correspondencia, agencialidad y causalidad."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 169', 'Según el modelo de la Teoría de la acción razonada, ¿qué componente determina la actitud general hacia una conducta?:', '["La intención conductual.", "Creencia que la persona tiene sobre las consecuencias de la conducta.", "La norma subjetiva.", "Las creencias normativas."]'::jsonb, 1, null, false),
('PIR 19', 'Pregunta 170', 'Según la Teoría de la categorización del Yo, la "saliencia" de una categoría social en una situación concreta es función de dos procesos denominados:', '["Prototipicidad y homogeneidad.", "Anclaje y comparación.", "Accesibilidad y ajuste.", "Atribución y heterogeneidad."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 171', '¿Cuál de las siguientes opciones NO recoge una de las estrategias de obtención de identidad social positiva propuestas por la Teoría de la identidad social?:', '["Creatividad social.", "Movilidad individual.", "Competición social.", "Facilitación social."]'::jsonb, 3, null, false),
('PIR 19', 'Pregunta 172', '¿Cuál de los siguientes modelos establece la existencia de una "vía central" y una "vía periférica" en los procesos de persuasión:', '["El modelo de probabilidad de elaboración.", "El modelo de activación automática.", "El modelo del comportamiento planificado.", "El modelo de continuidad."]'::jsonb, 0, null, false),
('PIR 19', 'Pregunta 173', 'Cuando un sujeto se conforma a las expectativas de una grupo debido a su temor a la desaprobación social, al castigo del grupo, se está produciendo un proceso de:', '["Influencia informativa.", "Conversión.", "Influencia normativa.", "Reactancia psicológica."]'::jsonb, 2, null, false),
('PIR 19', 'Pregunta 174', '¿Cuál de los siguientes NO es un factor que favorezca la aparición del denominado "pensamiento de grupo" según el modelo propuesto por Janis?:', '["La alta cohesión grupal.", "La heterogeneidad de los miembros en actitudes e ideología.", "El aislamiento del grupo respecto de la influencia externa.", "La existencia de un contexto de alto estrés."]'::jsonb, 1, null, false),
